name: video-service

x-environment: &environment
  APP_ORIGIN: ${APP_ORIGIN:-http://localhost:8080}
  SCRATCH_DIR: /scratch
  WORKER_REQUIRED: "true"
  MAX_UPLOAD_BYTES: ${MAX_UPLOAD_BYTES:-524288000}
  SCRATCH_MIN_FREE_BYTES: ${SCRATCH_MIN_FREE_BYTES:-2147483648}
  POSTGRES_HOST: db
  POSTGRES_PORT: "5432"
  POSTGRES_DB: ${POSTGRES_DB:-video_service}
  POSTGRES_USER: ${POSTGRES_USER:-video_service}
  POSTGRES_PASSWORD: ${POSTGRES_PASSWORD:?Run python3 scripts/prepare_env.py first}
  S3_ENDPOINT_URL: http://storage:8333
  S3_BUCKET: ${S3_BUCKET:-video-media}
  S3_REGION: ${S3_REGION:-us-east-1}
  S3_ACCESS_KEY: ${S3_ACCESS_KEY:?Run python3 scripts/prepare_env.py first}
  S3_SECRET_KEY: ${S3_SECRET_KEY:?Run python3 scripts/prepare_env.py first}

# Test credentials are generated separately by scripts/run_checks.py.
x-test-environment: &test-environment
  APP_ORIGIN: http://localhost:8080
  POSTGRES_HOST: test-db
  POSTGRES_PORT: "5432"
  POSTGRES_DB: video_service_test
  POSTGRES_USER: video_service_test
  POSTGRES_PASSWORD: ${TEST_POSTGRES_PASSWORD:-}
  S3_ENDPOINT_URL: http://test-storage:8333
  S3_BUCKET: video-test-media
